// Ice Isle houses (Shifat Oct 31 9:56 PM 'use house models from Polyfork, optimize them'): Polyfork free models mountain-refuge-hut-32ab1e and
// piste-patrol-hut-17a90a (alpine-and-snow kit; grass tufts dropped, door/shutter pivots baked shut). Baked to int16 positions (0.25 mm) + 8-bit
// vertex colours, no textures, no normals (flat shaded) - all houses merge into 1 draw call (+1 for the lit windows). Licence: https://polyfork.dev/licensing
import * as THREE from 'three';
const b64 = (s: string) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
export type HutData = { p: string; c: string; size: [number, number, number] };
export const HUTS: HutData[] = [
    { p: '', c: '', size: [6, 4.41, 6] },
    { p: '', c: '', size: [3.96, 4.66, 3.96] },
];
/* one hut as a non-indexed geometry with position + color; `glass` = the near-black window/door glass triangles (they glow at night) */
export function hutGeo(i: number): { body: THREE.BufferGeometry; glass: THREE.BufferGeometry } {
    const h = HUTS[i], q = new Int16Array(b64(h.p).buffer), c = b64(h.c), n = q.length / 3;
    const bp: number[] = [], bc: number[] = [], gp: number[] = [];
    for (let t = 0; t < n; t += 3) {
        let lum = 0; for (let k = 0; k < 3; k++) lum += c[(t + k) * 3] + c[(t + k) * 3 + 1] + c[(t + k) * 3 + 2];
        const glass = lum / 9 < 16;
        for (let k = 0; k < 3; k++) { const v = t + k; const P = [q[v * 3] / 4000, q[v * 3 + 1] / 4000, q[v * 3 + 2] / 4000];
            if (glass) gp.push(...P); else { bp.push(...P); bc.push(c[v * 3] / 255, c[v * 3 + 1] / 255, c[v * 3 + 2] / 255); } }
    }
    const body = new THREE.BufferGeometry(); body.setAttribute('position', new THREE.Float32BufferAttribute(bp, 3)); body.setAttribute('color', new THREE.Float32BufferAttribute(bc, 3)); body.computeVertexNormals();
    const glass = new THREE.BufferGeometry(); glass.setAttribute('position', new THREE.Float32BufferAttribute(gp, 3));
    return { body, glass };
}
